// Main.java
abstract class Pembayaran {
    abstract int biaya(int tagihan);

    int total(int tagihan) {
        return tagihan + biaya(tagihan);
    }
}

class Tunai extends Pembayaran {
    @Override
    int biaya(int tagihan) {
        return ____;
    }
}

class Transfer extends Pembayaran {
    @Override
    int biaya(int tagihan) {
        return ____;
    }
}

public class Main {
    public static void main(String[] args) {
        Pembayaran[] cara = { new Tunai(), new Transfer() };
        for (Pembayaran p : cara) {
            System.out.println("Total: " + p.total(10000));
        }
    }
}

